/* Local proxy worker for pdf.js
 * Tries multiple sources to load the actual pdf.js worker code.
 * This avoids hardcoding the dev server port and allows offline-friendly fallback chains.
 */
/* eslint-disable no-undef */
(function(){
  // Ensure self references window-like object for worker expectations
  try { self.window = self.window || self; } catch(_) {}

  var version = '5.3.93';
  var tried = [];

  function tryImport(url){
    try {
      importScripts(url);
      return true;
    } catch(e){
      tried.push({ url: url, error: String(e && e.message || e) });
      return false;
    }
  }

  // Preferred CDN (jsDelivr)
  if (tryImport('https://cdn.jsdelivr.net/npm/pdfjs-dist@'+version+'/build/pdf.worker.min.js')) return;
  // Fallback CDN (cdnjs)
  if (tryImport('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/'+version+'/pdf.worker.min.js')) return;
  // Unpkg fallback
  if (tryImport('https://unpkg.com/pdfjs-dist@'+version+'/build/pdf.worker.min.js')) return;

  // As a last resort, attempt non-minified
  if (tryImport('https://cdn.jsdelivr.net/npm/pdfjs-dist@'+version+'/build/pdf.worker.js')) return;

  // If all failed, surface a clear error in the worker context
  throw new Error('Failed to load pdf.worker from all sources: '+ JSON.stringify(tried));
})();


